/**
 * @summary Get recent analyses for the authenticated user
 */
export const getGetRecentAnalysesUrl = (params?: GetRecentAnalysesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/dashboard/recent-analyses?${stringifiedParams}`
    : `/api/dashboard/recent-analyses`;
};

export const getRecentAnalyses = async (
  params?: GetRecentAnalysesParams,
  options?: RequestInit,
): Promise<Analysis[]> => {
  return customFetch<Analysis[]>(getGetRecentAnalysesUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetRecentAnalysesQueryKey = (
  params?: GetRecentAnalysesParams,
) => {
  return [
    `/api/dashboard/recent-analyses`,
    ...(params ? [params] : []),
  ] as const;
};

